const q = $('Webhook IA').item.json.query || {};
const id = Number(q.id) || 0;
const tipo = (String(q.tipo || 'entrevista') === 'carencias') ? 'carencias' : 'entrevista';
const selectSql = `SELECT id, title, company, location, keywords, description, (SELECT data->>'perfil' FROM empleo.settings WHERE id=1) AS perfil_cfg, (SELECT data->'ia'->>'groq_key' FROM empleo.settings WHERE id=1) AS ia_groq_cfg, (SELECT data->'ia'->>'gemini_key' FROM empleo.settings WHERE id=1) AS ia_gemini_cfg, (SELECT data->'ia'->>'xai_key' FROM empleo.settings WHERE id=1) AS ia_xai_cfg FROM empleo.job_offers WHERE id=${id};`;
return [{ json: { id: id, tipo: tipo, selectSql: selectSql } }];

const helpers = this.helpers;
const NL = String.fromCharCode(10);
const _cfg = ($('DB leer oferta').first() || {}).json || {};
const GROQ_KEY = String(_cfg.ia_groq_cfg || '').trim() || $env['GROQ_API_KEY'] || '';
const GEMINI_KEY = String(_cfg.ia_gemini_cfg || '').trim() || $env['GEMINI_API_KEY'] || '';
const GROK_KEY = String(_cfg.ia_xai_cfg || '').trim() || $env['XAI_API_KEY'] || '';
const providers = [
  { name: 'gemini', url: 'https://cms.example.com/llm/gemini/v1beta/openai/chat/completions', key: GEMINI_KEY, model: 'gemini-3.6-flash' },
  { name: 'groq', url: 'https://cms.example.com/llm/groq/openai/v1/chat/completions', key: GROQ_KEY, model: 'openai/gpt-oss-120b' },
  { name: 'grok', url: 'https://cms.example.com/llm/xai/v1/chat/completions', key: GROK_KEY, model: 'grok-3' },
  { name: 'ollama', url: 'http://ollama:11434/v1/chat/completions', key: '', model: 'qwen3:8b' }
];
const PERFIL = ['<<< PON TU PERFIL AQUI: ver automation/n8n/profile.example.md >>>'].join(NL);
const o = ($('DB leer oferta').first() || { json: {} }).json;
const tipo = ($('Prep IA').first() || { json: {} }).json.tipo || 'entrevista';
const oferta = 'OFERTA: ' + (o.title||'') + ' en ' + (o.company||'') + ' (' + (o.location||'') + ')' + NL + 'TECNOLOGIAS: ' + (o.keywords||'') + NL + 'DESCRIPCION:' + NL + String(o.description||'').slice(0,3000);
let SYS;
if (tipo === 'carencias') {
  SYS = ['Eres el coach de carrera de el candidato (perfil abajo). Analiza ESTA oferta frente a su perfil y responde en markdown, conciso y accionable, con estas 3 secciones:','1) QUE YA TIENE que encaja con la oferta (para destacarlo en CV/entrevista).','2) QUE LE FALTA (tecnologias o experiencia que pide la oferta y el candidato no tiene). Se honesto.','3) MINI-PLAN para cubrir cada carencia (recurso/curso/proyecto rapido de 1-2 semanas).','Usa SOLO datos reales del perfil; no inventes. == PERFIL ==', PERFIL].join(NL);
} else {
  SYS = ['Eres el preparador de entrevistas de el candidato (perfil abajo). Para ESTA oferta genera en markdown:','1) 8-10 PREGUNTAS de entrevista probables (tecnicas y de encaje) que le harian para este puesto.','2) Bajo cada pregunta, un apunte breve de COMO responder apoyandose en su experiencia real del perfil.','3) 3 PREGUNTAS que el candidato deberia hacer al entrevistador.','Concreto y util, sin relleno. == PERFIL ==', PERFIL].join(NL);
}
let content = '', used = 'none';
for (const p of providers) {
  if (p.name !== 'ollama' && !p.key) continue;
  try {
    const headers = { 'Content-Type': 'application/json' };
    if (p.key) headers['Authorization'] = 'Bearer ' + p.key;
    const res = await helpers.httpRequest({ method: 'POST', url: p.url, headers: headers, body: { model: p.model, messages: [{ role: 'system', content: SYS }, { role: 'user', content: oferta }], temperature: 0.5, max_tokens: 2048 }, json: true, timeout: 120000 });
    const c = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || '';
    if (c && c.trim().length > 400) { content = c; used = p.name; break; }
    if (c && !content) { content = c; used = p.name; }
  } catch (e) {}
}
if (!content) content = '(no se pudo generar, revisa las IA)';
const esc = v => `'` + String(v==null?``:v).replace(/'/g,`''`) + `'`;
const idNum = Number(o.id)||0;
const updateSql = `INSERT INTO empleo.ai_docs (offer_id, tipo, texto, ia, created_at) VALUES (`+idNum+`, `+esc(tipo)+`, `+esc(content)+`, `+esc(used)+`, now()) ON CONFLICT (offer_id, tipo) DO UPDATE SET texto=EXCLUDED.texto, ia=EXCLUDED.ia, created_at=now();`;
const msg = (tipo==='carencias'?'Analisis de carencias':'Prep de entrevista')+' listo: '+(o.title||'')+' - '+(o.company||'');
return [{ json: { updateSql: updateSql, msg: msg } }];
